#if UNITY_EDITOR
using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;
using EchoProtocol.Campaign;using EchoProtocol.Echo;using EchoProtocol.Interaction;using EchoProtocol.Player;using EchoProtocol.Presentation;
using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
// Reproducible real-input approaches. The house prerequisite/start pose and one
// temporary obstruction are declared fixtures; no interaction callback is invoked.
public sealed class InteractionApproachProbe:MonoBehaviour {
 static readonly BindingFlags Private=BindingFlags.Instance|BindingFlags.NonPublic;
 FirstPersonController player;PlayerInteractor interactor;PlayerInput input;Camera view;GameSession session;CampaignDirector campaign;HouseMemory house;HouseTelephone phone;LoopController loop;
 Keyboard keyboard;Mouse mouse;InputDevice[] originalDevices;string originalScheme;bool originalAuto,oldSuppress,configured,running,assertFixes;InputSettings.EditorInputBehaviorInPlayMode oldBehavior;
 Key[] keys=Array.Empty<Key>();float yaw,pitch,sensitivity;string output,phase;int fixtures;readonly List<string> checks=new List<string>();readonly List<object> measurements=new List<object>();GameObject obstruction;
 public string Status{get;private set;}="starting";
 static T F<T>(object o,string n)=>(T)o.GetType().GetField(n,Private).GetValue(o);
 public static void Run(string label,bool verifyFixes=true){if(!Application.isPlaying)throw new Exception("Fresh Play required");var p=new GameObject("Temporary interaction approach probe").AddComponent<InteractionApproachProbe>();p.assertFixes=verifyFixes;p.output="Docs/VisualEvidence/2026-10-02-Reconstruction/interaction-"+label;Directory.CreateDirectory(p.output);p.StartCoroutine(p.Guarded(p.Execute()));}
 IEnumerator Guarded(IEnumerator r){var stack=new Stack<IEnumerator>();stack.Push(r);while(stack.Count>0){object n;try{if(!stack.Peek().MoveNext()){stack.Pop();continue;}n=stack.Peek().Current;}catch(Exception e){Finish(false,e.ToString());yield break;}if(n is IEnumerator child)stack.Push(child);else yield return n;}}
 void Check(bool value,string text){if(!value)throw new Exception(text);checks.Add(text);}
 IEnumerator Execute(){
  player=FindFirstObjectByType<FirstPersonController>();view=player.GetComponentInChildren<Camera>();input=player.GetComponent<PlayerInput>();interactor=player.GetComponent<PlayerInteractor>();session=FindFirstObjectByType<GameSession>();campaign=FindFirstObjectByType<CampaignDirector>();house=FindFirstObjectByType<HouseMemory>();phone=FindFirstObjectByType<HouseTelephone>();loop=FindFirstObjectByType<LoopController>();
  Check(session.IsPaused&&!session.HasStarted,"Fresh real title");oldSuppress=campaign.SuppressSaves;campaign.SuppressSaves=true;sensitivity=F<float>(player,"lookSensitivity");yaw=player.transform.eulerAngles.y;pitch=F<float>(player,"pitch");Configure();running=true;
  yield return Press(Key.Enter);Check(!session.IsPaused,"Enter starts actual controls");
  phase="reception approach";yield return Go(.35f,-5.5f,0);var letter=FindObjectsByType<CampaignStation>(FindObjectsSortMode.None).Single(s=>s.Kind==StationKind.IntroLetter);yield return Aim(letter.GetComponent<Collider>().bounds.center);Check(interactor.TryGetTarget(out var t)&&ReferenceEquals(t,letter),"Real approach reaches reception document");yield return Capture("01-reception-focus");
  if(output.EndsWith("focus-notification")){
   phase="declared focus notification boundary";fixtures++;
   interactor.SendMessage("OnApplicationFocus",false,SendMessageOptions.RequireReceiver);session.SendMessage("OnApplicationFocus",false,SendMessageOptions.RequireReceiver);
   Check(session.IsPaused&&!interactor.HasUsableFocus,"focus-loss notification pauses the session and clears physical focus");
   keys=new[]{Key.E};yield return new WaitForSecondsRealtime(.2f);Check(F<string>(session,"documentTitle")==null,"E during lost focus cannot open the document");
   interactor.SendMessage("OnApplicationFocus",true,SendMessageOptions.RequireReceiver);session.SendMessage("OnApplicationFocus",true,SendMessageOptions.RequireReceiver);
   keys=new[]{Key.E,Key.Enter};yield return new WaitForSecondsRealtime(.15f);keys=new[]{Key.E};yield return new WaitForSecondsRealtime(.3f);
   Check(!session.IsPaused&&F<string>(session,"documentTitle")==null,"real Enter resumes but E held across focus gain cannot dispatch");
   keys=Array.Empty<Key>();yield return Wait(.15f);Check(interactor.TryGetTarget(out var resumed)&&ReferenceEquals(resumed,letter),"released key permits the same visible document to regain focus");
   yield return Press(Key.E);Check(session.IsPaused&&F<string>(session,"documentTitle")=="La llave de 6B","fresh E after focus recovery opens the actual selected document");
   yield return Capture("02-focus-recovery-document");Finish(true,"");yield break;
  }
  keys=new[]{Key.E};yield return new WaitForSecondsRealtime(.18f);Check(session.IsPaused&&F<string>(session,"documentTitle")=="La llave de 6B","E opens actual reception letter");
  keys=new[]{Key.E,Key.Escape};yield return new WaitForSecondsRealtime(.13f);keys=new[]{Key.E};yield return new WaitForSecondsRealtime(.3f);
  measurements.Add(new{caseName="document-close-while-E-held",paused=session.IsPaused,document=F<string>(session,"documentTitle")});if(assertFixes)Check(!session.IsPaused,"Held E cannot reopen a document when controls resume");
  keys=Array.Empty<Key>();yield return new WaitForSecondsRealtime(.1f);if(session.IsPaused)yield return Press(Key.Escape);Check(!session.IsPaused,"Release and explicit Escape recover controls");
  yield return Press(Key.H);Check(session.IsPaused,"H pauses from document recovery");yield return Press(Key.H);Check(!session.IsPaused,"H restores controls");
  yield return Aim(letter.GetComponent<Collider>().bounds.center);int before=loop.CompletedLoopCount;keys=new[]{Key.R,Key.E};yield return new WaitForSecondsRealtime(.12f);keys=Array.Empty<Key>();yield return new WaitForSecondsRealtime(.15f);
  measurements.Add(new{caseName="simultaneous-R-E",paused=session.IsPaused,recalls=loop.CompletedLoopCount-before,document=F<string>(session,"documentTitle")});if(assertFixes)Check(!session.IsPaused&&loop.CompletedLoopCount==before+1,"RECALL wins the R+E chord; no ghost document action");if(session.IsPaused)yield return Press(Key.Escape);
  phase="house prerequisite fixture";campaign.PrepareHouseProbe();house.EnterHouse();player.ResetPose(new Vector3(0,.03f,-53.3f),Quaternion.identity);fixtures++;yaw=0;pitch=0;yield return Wait(.3f);
  phase="normal phone approach";yield return Go(0,-52.3f,0);yield return Go(-2,-52.3f,270);yield return Go(-3.45f,-51.9f,270);
  var target=FindObjectsByType<HouseInteraction>(FindObjectsSortMode.None).Single(h=>h.Kind==HouseInteractionKind.Telephone);
  var handset=F<Transform>(phone,"handset").GetComponentInChildren<Renderer>();var body=FindObjectsByType<Renderer>(FindObjectsSortMode.None).Single(r=>r.name=="TelephoneBody");
  var points=new[]{body.bounds.center+Vector3.up*body.bounds.extents.y*.9f,handset.bounds.center+Vector3.up*handset.bounds.extents.y*.6f+Vector3.forward*handset.bounds.extents.z*.7f,handset.bounds.center+Vector3.up*handset.bounds.extents.y*.6f-Vector3.forward*handset.bounds.extents.z*.7f};
  for(int i=0;i<points.Length;i++){yield return Aim(points[i]);bool found=interactor.TryGetTarget(out var selected)&&ReferenceEquals(selected,target);measurements.Add(new{caseName="visible-phone-part-"+i,found,canInteract=found&&selected.CanInteract(player.gameObject),point=points[i].ToString("F3"),distance=Vector3.Distance(view.transform.position,points[i])});if(assertFixes)Check(found&&selected.CanInteract(player.gameObject),"Visible phone part "+i+" resolves to the real telephone owner");yield return Capture("02-phone-part-"+i);}
  if(assertFixes){int total=0,lost=0;float y=yaw,p=pitch,end=Time.realtimeSinceStartup+1.2f;while(Time.realtimeSinceStartup<end){yaw=y+Mathf.Sin(Time.realtimeSinceStartup*8f)*.25f;pitch=p+Mathf.Sin(Time.realtimeSinceStartup*6f)*.25f;yield return null;total++;if(!interactor.TryGetTarget(out var stable)||!ReferenceEquals(stable,target))lost++;}Check(lost==0,"Small natural aim movement stays on visible handset");measurements.Add(new{caseName="handset-small-look-motion",totalFrames=total,lostFrames=lost});}
  yield return Aim(target.GetComponent<Collider>().bounds.center);Check(interactor.TryGetTarget(out var ph)&&ReferenceEquals(ph,target),"Original phone interaction centre is physically reachable");
  keys=new[]{Key.E};yield return new WaitForSecondsRealtime(1.2f);Check(house.HasAnswered&&phone.IsOffHook&&!phone.IsMoving,"Held E lifts phone exactly once");keys=Array.Empty<Key>();yield return Wait(.15f);
  // Physical obstruction at the midpoint: uses real E with a declared temporary collider.
  Vector3 point=target.GetComponent<Collider>().bounds.center;Vector3 delta=point-view.transform.position;
  obstruction=GameObject.CreatePrimitive(PrimitiveType.Cube);obstruction.name="TEST ONLY opaque interaction obstruction";obstruction.transform.position=view.transform.position+delta*.5f;obstruction.transform.rotation=Quaternion.LookRotation(delta);obstruction.transform.localScale=new Vector3(1.2f,1.2f,.12f);fixtures++;Physics.SyncTransforms();yield return Wait(.12f);
  Check(!interactor.TryGetTarget(out var blocked)||!ReferenceEquals(blocked,target),"Solid obstruction hides phone target");yield return Press(Key.E);Check(phone.IsOffHook,"E cannot operate through obstruction");Destroy(obstruction);obstruction=null;yield return Wait(.2f);
  yield return Press(Key.E);yield return Wait(.8f);Check(!phone.IsOffHook,"New E release/press hangs up once");
  phase="reach limit and target switch";yield return Go(-2,-52.3f,90);yield return Go(-1.85f,-49.95f,0);yield return Aim(target.GetComponent<Collider>().bounds.center);
  float edgeDistance=Vector3.Distance(view.transform.position,target.GetComponent<Collider>().ClosestPoint(view.transform.position));Check(edgeDistance>interactor.InteractionDistance+.08f,"phone physically exceeds maximum retained reach");Check(!interactor.TryGetTarget(out var far)||!ReferenceEquals(far,target),"phone outside reach is not selected");yield return Press(Key.E);Check(!phone.IsOffHook,"out-of-reach E cannot lift phone");
  var document=FindObjectsByType<HouseInteraction>(FindObjectsSortMode.None).Single(h=>h.Kind==HouseInteractionKind.Document);yield return Aim(document.GetComponent<Collider>().bounds.center);Check(interactor.TryGetTarget(out var adjacent)&&ReferenceEquals(adjacent,document),"look switches from unreachable phone to actual nearby document");yield return Press(Key.E);Check(session.IsPaused,"newly selected document receives E");yield return Press(Key.Escape);yield return Go(-2,-52.3f,180);
  phase="reserve normal approach";yield return Go(-2,-52.3f,90);yield return Go(0,-52.3f,90);yield return Go(0,-50.8f,0);var socket=FindObjectsByType<HouseInteraction>(FindObjectsSortMode.None).Single(h=>h.Kind==HouseInteractionKind.HallSocket);yield return Aim(socket.GetComponentInChildren<Collider>().bounds.center);
  Check(interactor.TryGetTarget(out var rs)&&ReferenceEquals(rs,socket),"Hall reserve selected after physical approach");keys=new[]{Key.E};yield return new WaitForSecondsRealtime(.8f);Check(house.PowerLocation==HousePowerLocation.Carried,"Held E takes one reserve without duplicate toggle");keys=Array.Empty<Key>();yield return Wait(.15f);yield return Press(Key.E);Check(house.PowerLocation==HousePowerLocation.Hall,"Separate E returns reserve");yield return Capture("03-hall-reserve");Finish(true,"");
 }
 IEnumerator Go(float x,float z,float facing){yield return Face(facing,0);float end=Time.realtimeSinceStartup+20;while(Vector2.Distance(new Vector2(player.transform.position.x,player.transform.position.z),new Vector2(x,z))>.10f){if(Time.realtimeSinceStartup>end)throw new Exception("Blocked physical approach "+player.transform.position+" -> "+x+","+z);var d=player.transform.InverseTransformDirection(new Vector3(x,player.transform.position.y,z)-player.transform.position);var list=new List<Key>();if(d.x>.055f)list.Add(Key.D);else if(d.x<-.055f)list.Add(Key.A);if(d.z>.055f)list.Add(Key.W);else if(d.z<-.055f)list.Add(Key.S);keys=list.ToArray();yield return null;}yield return Wait(.12f);}
 IEnumerator Aim(Vector3 p){var d=p-view.transform.position;yield return Face(Mathf.Atan2(d.x,d.z)*Mathf.Rad2Deg,-Mathf.Atan2(d.y,new Vector2(d.x,d.z).magnitude)*Mathf.Rad2Deg);}
 IEnumerator Face(float y,float p){yaw=y;pitch=p;keys=Array.Empty<Key>();float end=Time.realtimeSinceStartup+5;while(Mathf.Abs(Mathf.DeltaAngle(player.transform.eulerAngles.y,yaw))>.4f||Mathf.Abs(F<float>(player,"pitch")-pitch)>.4f){if(Time.realtimeSinceStartup>end)throw new Exception("Mouse aim failed; focused="+Application.isFocused);yield return null;}yield return Wait(.12f);}
 IEnumerator Press(Key key){keys=Array.Empty<Key>();yield return new WaitForSecondsRealtime(.07f);keys=new[]{key};yield return new WaitForSecondsRealtime(.1f);keys=Array.Empty<Key>();yield return new WaitForSecondsRealtime(.14f);}
 IEnumerator Wait(float seconds){keys=Array.Empty<Key>();yield return new WaitForSecondsRealtime(seconds);}
 IEnumerator Capture(string name){yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(output+"/"+name+"-Game.png",t.EncodeToPNG());Destroy(t);}
 void Configure(){originalDevices=input.devices.ToArray();originalScheme=input.currentControlScheme;originalAuto=input.neverAutoSwitchControlSchemes;oldBehavior=InputSystem.settings.editorInputBehaviorInPlayMode;keyboard=InputSystem.AddDevice<Keyboard>("InteractionProbeKeyboard");mouse=InputSystem.AddDevice<Mouse>("InteractionProbeMouse");input.neverAutoSwitchControlSchemes=true;input.SwitchCurrentControlScheme("Keyboard&Mouse",keyboard,mouse);InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;configured=true;InputSystem.onBeforeUpdate+=InputUpdate;}
 void InputUpdate(){if(!running||InputState.currentUpdateType!=InputUpdateType.Dynamic)return;InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));var delta=new Vector2(Mathf.Clamp(Mathf.DeltaAngle(player.transform.eulerAngles.y,yaw),-10,10)/sensitivity,Mathf.Clamp(F<float>(player,"pitch")-pitch,-10,10)/sensitivity);InputSystem.QueueStateEvent(mouse,new MouseState{delta=delta});}
 void Finish(bool ok,string error){Status=ok?"PASS":"FAIL";Cleanup();File.WriteAllText(output+"/result.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{status=Status,error,phase,scope=output.EndsWith("focus-notification")?"Isolated real movement/mouse/E/Enter with one explicit Unity OnApplicationFocus false/true notification fixture. Verifies callback/input boundary, NOT operating-system focus transitions or human feel.":"Input System E/R/H/Escape and physical WASD/mouse approaches; one prior-house API/start-pose fixture, one temporary obstruction. No direct interaction callback. Measurements diagnose baseline failures; PASS means route ran, not every measurement was accepted.",fixtureCount=fixtures,assertFixes,checks,measurements},Newtonsoft.Json.Formatting.Indented));Debug.Log("Interaction approach "+Status+" "+error);}
 void Cleanup(){running=false;InputSystem.onBeforeUpdate-=InputUpdate;if(obstruction)Destroy(obstruction);if(campaign)campaign.SuppressSaves=oldSuppress;if(session)session.SetPaused(true);if(!configured)return;configured=false;InputSystem.settings.editorInputBehaviorInPlayMode=oldBehavior;if(input){input.neverAutoSwitchControlSchemes=originalAuto;if(originalDevices.Length>0&&!string.IsNullOrEmpty(originalScheme))input.SwitchCurrentControlScheme(originalScheme,originalDevices);}if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);if(mouse!=null&&mouse.added)InputSystem.RemoveDevice(mouse);}
 void OnDestroy(){Cleanup();}
}
#endif
